var accepted = Object.create(null);
var acceptedSize = 0;
function normKey(u) {
  try {
    var a = new URL(u, location.href);
    return a.origin + a.pathname;
  } catch (e) {
    return String(u).split('#')[0].split('?')[0];
  }
}
MS.hook('resource:keep', function (kind, url) {
  var u = String(url || '');
  if (!u) return true;
  var key = normKey(u);
  var prev = accepted[key];
  if (!prev) {
    if (acceptedSize > 8000) { accepted = Object.create(null); acceptedSize = 0; }
    accepted[key] = u;
    acceptedSize++;
    return true;
  }
  return prev === u;
});
